<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class PassengerRequirementEditor {
 public static function register(): void { add_action('admin_post_avanik_save_passenger_requirements',[self::class,'save']); add_shortcode('avanik_passenger_requirements',[self::class,'render']); }
 public static function render(array $atts=[]): string { if(!is_user_logged_in())return '<p>لطفاً وارد حساب شوید.</p>'; $id=(int)($atts['product_id']??($_GET['product_id']??0)); $p=ProductRepository::find($id); if(!$p)return '<p>محصول پیدا نشد.</p>'; $fields=PassengerRequirements::for_product($p); $labels=['first_name'=>'نام','last_name'=>'نام خانوادگی','phone'=>'موبایل','email'=>'ایمیل','national_id'=>'کد ملی','nationality'=>'ملیت','date_of_birth'=>'تاریخ تولد','passport_no'=>'شماره پاسپورت','passport_expiry'=>'تاریخ انقضای پاسپورت','gender'=>'جنسیت']; ob_start(); ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" dir="rtl"><?php wp_nonce_field('avanik_save_passenger_requirements'); ?><input type="hidden" name="action" value="avanik_save_passenger_requirements"><input type="hidden" name="product_id" value="<?php echo esc_attr($id); ?>"><h3>اطلاعات موردنیاز مسافر</h3><?php foreach($labels as $key=>$label): ?><label style="display:block;margin:8px 0"><input type="checkbox" name="fields[]" value="<?php echo esc_attr($key); ?>" <?php checked(in_array($key,$fields,true)); ?>> <?php echo esc_html($label); ?></label><?php endforeach; ?><button class="button button-primary" type="submit">ذخیره</button></form><?php return (string)ob_get_clean(); }
 public static function save(): void { if(!is_user_logged_in()||!check_admin_referer('avanik_save_passenger_requirements'))wp_die('Unauthorized'); $id=(int)($_POST['product_id']??0); $p=ProductRepository::find($id); if(!$p)wp_die('Product not found'); $fields=array_map('sanitize_key',(array)($_POST['fields']??[])); $type=sanitize_key($p['product_type']??''); if($type===PassengerRequirements::DOMESTIC_FLIGHT)$fields=array_values(array_diff($fields,['passport_no','passport_expiry'])); PassengerRequirements::set_custom($id,$fields); wp_safe_redirect(wp_get_referer()?:home_url()); exit; }
}